/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ReactNode } from 'react';

import { Container as ContainerPrimitive, Poster as PosterPrimitive } from '../../skin-primitives';
import { ErrorDialog } from '../shared/skins/scaffold/shared/error-dialog';
import { Indicators } from '../shared/skins/scaffold/shared/indicators';
import { StatusAnnouncer } from '../shared/skins/scaffold/shared/status-announcer';
import { Poster } from '../shared/skins/scaffold/shared/video-feedback';
import { LiveVideoGestures } from '../shared/skins/shared/live-video/behaviors/gestures';
import { LiveVideoHotkeys } from '../shared/skins/shared/live-video/behaviors/hotkeys';
import { LiveVideoControls } from './controls';

export interface LiveVideoSkinProps extends Omit<ContainerPrimitive.Props, 'children'> {
  children?: ReactNode;
  renderPoster?: PosterPrimitive.ImageProps['render'];
}

export function LiveVideoSkin({ children, className, renderPoster, ...props }: LiveVideoSkinProps = {}) {
  return (
    <ContainerPrimitive
      className={cn('media-skin', 'media-container', 'media-video', className)}
      data-theme="scaffold"
      data-preset="live-video"
      {...props}
    >
      {children}
      <Poster renderImage={renderPoster} />
      <ErrorDialog />
      <LiveVideoControls />

      <LiveVideoHotkeys />
      <LiveVideoGestures />
      <StatusAnnouncer />
      <Indicators />
    </ContainerPrimitive>
  );
}
